def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.85))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    aggressive_count = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 90:
                aggressive_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    urgency = 0.0
    if hp <= 2:
        urgency += 0.55
    elif hp <= 4:
        urgency += 0.3
    if no_water_days >= 2:
        urgency += 0.5
    elif no_water_days >= 1:
        urgency += 0.25
    if day >= 8:
        urgency += 0.1

    if supply >= 22:
        base = 18.0
    elif supply >= 19:
        base = 28.0
    elif supply >= 17:
        base = 42.0
    else:
        base = 58.0

    base += 22.0 * scarcity
    base += 38.0 * urgency

    if highest_prev >= 105:
        if urgency < 0.45:
            bid = min(base, 26.0)
        else:
            bid = max(base, highest_prev - 4.0)
    elif highest_prev >= 90:
        if urgency < 0.35 and supply >= 19:
            bid = min(base, 24.0)
        else:
            bid = max(base, avg_prev + 2.0)
    elif highest_prev > 0:
        bid = max(base, highest_prev + 1.5)
    else:
        bid = base

    if aggressive_count >= 2 and urgency < 0.45 and supply >= 19:
        bid = min(bid, 22.0)

    reserve = 0.0
    if hp > 4 and no_water_days == 0:
        reserve = 35.0
    elif hp > 2:
        reserve = 15.0

    max_affordable = max(0.0, budget - reserve)
    if urgency >= 0.75:
        max_affordable = budget

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, 82.0)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(bid, 55.0 if supply >= 19 else 68.0)

    bid = min(bid, max_affordable if max_affordable > 0 else budget)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

