def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Pressure from yesterday: use bids from alive opponents only.
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    pressure_bid = max(prev_bids) if prev_bids else 0.0

    # Supply regime: compute a soft urgency factor.
    # If supply is near MIN_SUPPLY, competition likely tighter.
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    supply_ratio = max(0.0, min(1.0, supply_ratio))
    low_supply = 1.0 - supply_ratio

    # If I'm already in danger, bid more aggressively.
    danger = 0.0
    if my_hp <= 2.0:
        danger = 1.0
    elif my_hp <= 4.0:
        danger = 0.6
    if my_no_water_days >= 2:
        danger = max(danger, 0.7)

    # Base bid: target slightly above likely top survivor bid when pressure is moderate.
    # Otherwise, bid around a mid fraction of salary.
    if pressure_bid >= DAILY_SALARY * 0.45:
        target = pressure_bid + (8.0 + 10.0 * low_supply)
    else:
        target = DAILY_SALARY * (0.5 + 0.15 * low_supply)

    # Increase in danger.
    target *= (1.0 + 0.35 * danger)

    # Cap to avoid bankrupting; also ensure non-negative.
    # Keep some budget buffer for later days.
    max_affordable = my_budget * 0.9
    bid = min(max_affordable, target)

    # If bid is too small relative to pressure, bump to just above pressure.
    if pressure_bid > 0.0 and bid < pressure_bid * 0.95:
        bid = min(max_affordable, pressure_bid + 5.0)

    # Final safety clamp.
    if bid < 0.0:
        bid = 0.0
    return float(bid)
